-- Scholarship Enrichment Batch 14 — 2026-10-27
-- Gulf graduate additions verified first-hand from official sources:
--   954 KAUST Fellowship (King Abdullah University of Science and Technology)
--   955 MBZUAI Graduate Funding (Fully Funded M.Sc. and Ph.D. Programs)
--   956 Tamim Scholarship (Doha Institute for Graduate Studies)
-- Sources 3090 (KAUST Fees & Funding), 3091 (MBZUAI Graduate Ph.D. Admissions),
-- 3092 (Doha Institute Scholarships); links 954->3090, 955->3091, 956->3092.
-- NOTE ON IDS: the three scholarship INSERTs were executed in parallel with
-- RETURNING and completed KAUST (954) -> MBZUAI (955) -> Doha (956); the
-- mapping below is pinned from those RETURNING results. None of the three
-- universities has a record in the universities table (checked 2026-10-27),
-- so university_id is NULL and no university_scholarships rows were created.
-- Statements below replay the exact executed SQL with ids pinned.
-- See docs/SCHOLARSHIP_ENRICHMENT_BATCH_14_2026-10-27.md.

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (954, 'KAUST Fellowship', 'King Abdullah University of Science and Technology (KAUST)', 'Saudi Arabia', 'Full Tuition + Stipend', 0, 'Fall 2027 admission (M.S., M.S./Ph.D. and Ph.D.): Round 2 application opened 28 September 2026 and closes 3 January 2027 (decisions 25 February 2027; semester starts 29 August 2027). There is no separate fellowship application - every admitted student automatically receives the KAUST Fellowship. A Spring 2027 round for Ph.D. applicants only closed 27 September 2026.', '2027-01-03', 'fixed', NULL, NULL, $j$["Master's", "PhD"]$j$, $j$["Science and engineering M.S. and Ph.D. programmes across KAUST's divisions: Biological and Environmental Science and Engineering (BESE), Computer, Electrical and Mathematical Science and Engineering (CEMSE) and Physical Science and Engineering (PSE)"]$j$, '[]', NULL, 6.5, false, true, $desc$The KAUST Fellowship is the automatic funding package of King Abdullah University of Science and Technology (KAUST), the graduate research university at Thuwal on Saudi Arabia's Red Sea coast: every student admitted to a KAUST M.S., M.S./Ph.D. or Ph.D. programme receives it for the duration of their graduate studies (students funded through specific external sponsorship or partnership agreements may be excepted), and there is no separate scholarship application - the package is confirmed in the admission offer letter. The Fellowship covers full tuition and bench fees (worth up to USD 35,000 per year), a monthly stipend worth USD 20,000 per year for M.S. students and USD 25,000-30,000 per year for Ph.D. students (the Ph.D. rate steps up with credits completed - about USD 2,083 per month before 30 credits and USD 2,500 per month above 30 credits), base on-campus accommodation (shared for single students, two-bedroom for married students, with paid upgrades possible), health insurance for the student and eligible dependents living on campus, and relocation support covering visa, relocation and travel costs for the initial move and the return home on graduation. KAUST estimates the total value at USD 70,000-80,000 per year. Admission runs in rounds: for Fall 2027 entry (M.S., M.S./Ph.D. and Ph.D.), the open Round 2 runs from 28 September 2026 to 3 January 2027 with decisions on 25 February 2027 and the semester starting 29 August 2027; a Spring 2027 round for Ph.D. applicants only closed on 27 September 2026.$desc$, $req$Admission (and therefore the Fellowship) requires a relevant bachelor's degree for M.S. entry - or a master's for Ph.D. entry, with highly qualified bachelor's holders also considered for the Ph.D. and M.S./Ph.D. routes - in science or engineering fields matching KAUST's BESE, CEMSE and PSE divisions, plus English proficiency of at least IELTS 6.5 (KAUST code 4107) or TOEFL iBT 81, waived only for degrees earned in the United States, Canada, the United Kingdom, Ireland, Australia or New Zealand. The GRE is not required (a strong quantitative score is encouraged). No minimum GPA is published in KAUST's admission requirements, so min_gpa is not recorded; the published English minima make IELTS 6.5 the recorded min_ielts for Uzbek applicants, whose prior degrees do not qualify for the waiver. Admission is competitive and applicants are advised to submit all documents early and respond promptly to interview invitations. Students with external sponsorship or funding may not be eligible for the KAUST Fellowship itself.$req$, 'https://admissions.kaust.edu.sa/fees-funding', 'https://admissions.kaust.edu.sa/fees-funding', 'https://apply.kaust.edu.sa/apply/', 'annual', 'open', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 14) from KAUST's official admissions pages fetched the same day: Fees & Funding (full tuition and bench fees up to USD 35,000/year; stipend USD 20,000/year M.S. and USD 25,000-30,000 Ph.D.; base accommodation; health insurance; relocation support; total estimated value USD 70,000-80,000/year; students with external sponsorship may be ineligible); Admission Timeline (Fall 2027 Round 2 open 28 September 2026, deadline 3 January 2027, decisions 25 February 2027, semester starts 29 August 2027; Spring 2027 Ph.D.-only Round 1 closed 27 September 2026, semester starts 17 January 2027); and KAUST's published application requirements (minimum IELTS 6.5 / TOEFL iBT 81, waiver countries, GRE not required), corroborated by the admissions FAQ (no separate fellowship application; Ph.D. stipend steps from about USD 2,083 to USD 2,500 per month by credits on the onboarding page). award_amount is NULL (variable): stipend differs by degree level and, for Ph.D. students, by academic progress, and tuition is paid on top, so the figures live in funding_type; award_currency USD. deadline_date 2027-01-03 is the live Fall 2027 round closing with status 'open'. eligible_countries is empty: KAUST's published admission requirements impose no nationality restriction, and the Fellowship attaches to admission itself. university_id is NULL and no university_scholarships row is created - KAUST has no record in the universities table (checked 2026-10-27); create and backlink in a later university-records task. min_gpa NULL (none published); min_ielts 6.5 stored.$note$, NULL, NULL, 'USD', 'year', 'variable', NULL, 'Full tuition and bench fees (up to USD 35,000 per year) + monthly stipend (USD 20,000 per year M.S.; USD 25,000-30,000 per year Ph.D. depending on qualifications and academic progress) + base accommodation + health insurance + relocation support - automatic for all admitted students (KAUST estimates USD 70,000-80,000 total value per year)', 'Full tuition and bench fees are covered for the duration of the M.S. or Ph.D. programme.', 'Minimum IELTS 6.5 (KAUST code 4107) or TOEFL iBT 81; waived only for degrees from the US, Canada, UK, Ireland, Australia or New Zealand.', $j$["Online application for graduate admission to KAUST (no separate fellowship application)", "Degree certificates and transcripts", "Official IELTS 6.5+ or TOEFL iBT 81+ scores (unless eligible for the waiver)", "Curriculum vitae, statement of purpose and recommendation letters as required by the application portal", "Respond promptly to any interview invitation"]$j$, NULL, NULL, $json$[{"intake": "Fall 2027 (M.S., M.S./Ph.D., Ph.D.), Round 2", "opens": "2026-09-28", "deadline": "2027-01-03", "decisions": "2027-02-25", "semester_starts": "2027-08-29", "status": "open"}, {"intake": "Spring 2027 (Ph.D. only), Round 1", "deadline": "2026-09-27", "status": "closed"}, {"pattern": "KAUST runs admission rounds for Spring entry (Ph.D.) and Fall entry (M.S., M.S./Ph.D., Ph.D.); all admitted students automatically receive the KAUST Fellowship unless externally sponsored"}]$json$);

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (955, 'MBZUAI Graduate Funding (Fully Funded M.Sc. and Ph.D. Programs)', 'Mohamed bin Zayed University of Artificial Intelligence (MBZUAI)', 'United Arab Emirates', 'Full Tuition + Stipend', 0, 'Fall 2027 entry: application portal opened 7 September 2026; final deadline 15 December 2026 (5pm GST) for most M.Sc./Ph.D. programmes, 22 January 2027 for Computational Biology; decisions by 31 March 2027 and offer responses by 15 April 2027. Funding is considered through the admission process (no separate scholarship application).', '2026-12-15', 'fixed', NULL, NULL, $j$["Master's", "PhD"]$j$, $j$["MBZUAI's funded M.Sc. and Ph.D. programmes in artificial intelligence and related STEM fields (the fee-based Master in Applied Artificial Intelligence, MAAI, is excluded from university/faculty funding)"]$j$, '[]', NULL, NULL, false, true, $desc$Mohamed bin Zayed University of Artificial Intelligence (MBZUAI) in Abu Dhabi - the world's first graduate-level, research-based university dedicated to artificial intelligence - offers fully funded M.Sc. and Ph.D. programmes for the Fall 2027 entry cycle. Funded students receive free tuition fees, a monthly stipend, one return airfare to their home country each year, health insurance for the approved funding period, and university-sponsored UAE residence visa and Emirates ID (where eligible). The published stipend table lists monthly amounts by category, including international students at AED 15,500 per month on the M.Sc. and AED 17,500 per month on the Ph.D. (UAE nationals receive higher national rates). The funding model differs by degree: M.Sc. students are fully funded by the University throughout the programme, while Ph.D. students are centrally funded in Year 1 while they match with a faculty advisor, moving to the advisor's funding no later than the start of Year 2 - for Ph.D. students funding is therefore subject to a confirmed advisor match and satisfactory academic progress. The separate Master in Applied Artificial Intelligence (MAAI) is a fee-based programme (AED 170,000 total) and is explicitly excluded from this funding. Funded students must maintain an in-person presence on campus and disclose any external scholarships or fellowships (external funding normally replaces the university stipend rather than adding to it). Applications for the cycle opened 7 September 2026, with final deadlines of 15 December 2026 for most programmes and 22 January 2027 for Computational Biology.$desc$, $req$Applicants need a degree in a STEM field (computer science, electrical/computer engineering, mathematics, physics or another relevant science/engineering major) from an accredited institution recognised by the UAE Ministry of Education, with a minimum CGPA of 3.0 or 3.5 on a 4.0 scale depending on the programme; senior-level students may apply with a transcript and must file the official degree on admission, plus a Certificate of Recognition for degrees earned outside the UAE within the first semester. The application comprises the online form, a CV (academic background, work experience, publications, programming/coding skills), a statement of purpose, referee recommendations (minimum two for M.Sc., three for Ph.D.), a research statement (Ph.D.), valid proof of English proficiency submitted at the time of application, a passport copy and a photograph, and MBZUAI's screening exam (foundational mathematics and programming, plus machine learning/core computer science for Ph.D. applicants), after which a subset is invited to a technical interview. An application fee of AED 200 is payable after the screening exam (waived for applicants scoring 75%+ on the exam or reimbursed on enrollment); only one application per cycle is processed, and admission is highly competitive. The CGPA floor varies by programme (3.0 or 3.5) and the admissions pages publish no single English score, so min_gpa/min_ielts are not recorded.$req$, 'https://mbzuai.ac.ae/admissions/graduate-phd-admissions', 'https://mbzuai.ac.ae/admissions/graduate-phd-admissions', 'https://apply.mbzuai.ac.ae/ApplicantPortal', 'annual', 'open', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 14) from MBZUAI's official Graduate Ph.D. admissions and Graduate master's admissions pages, both fetched the same day and agreeing for the Fall 2027 cycle ('MBZUAI offers fully funded M.Sc. and Ph.D. programs'; M.Sc. fully funded by the University throughout; Ph.D. centrally funded in Year 1 then advisor-funded no later than Year 2, subject to a confirmed advisor match and satisfactory progress; funded-student package = free tuition, monthly stipend, one return airfare home per year, health insurance, university-sponsored UAE residence visa and Emirates ID; published stipend table - international students AED 15,500 M.Sc. and AED 17,500 Ph.D. (monthly, under the 'monthly stipend' heading), UAE nationals AED 37,500/43,500; MAAI excluded as fee-based at AED 170,000 total; external funding must be disclosed and normally replaces the stipend; portal opened 7 September 2026 for most programmes and 30 September 2026 for Computational Biology; final deadlines 15 December 2026 / 22 January 2027; decisions by 31 March 2027; AED 200 application fee after the screening exam with the 75%+ waiver; CGPA minimum 3.0 or 3.5 by programme). Note: older versions of MBZUAI's funding model described in the wider web (including a 'fee-paying by default' wording still visible in some cached snippets) do not match the live Fall-2027 admissions pages and were not used. award_amount is NULL (basis 'variable'): stipend rates differ by programme level and nationality and Ph.D. continuation hinges on the advisor match, so rates live in funding_type; award_currency AED, period 'month'. deadline_date 2026-12-15 is the main live closing with status 'open'. eligible_countries empty: the published stipend table carries an explicit international-students row. university_id is NULL and no university_scholarships row is created - MBZUAI has no record in the universities table (checked 2026-10-27). min_gpa/min_ielts NULL.$note$, NULL, NULL, 'AED', 'month', 'variable', NULL, 'Free tuition fees + monthly stipend (international students: AED 15,500/month M.Sc., AED 17,500/month Ph.D.; higher rates for UAE nationals) + one return airfare home each year + health insurance + university-sponsored UAE residence visa and Emirates ID (MAAI excluded)', 'Tuition fees are waived in full for funded M.Sc. and Ph.D. students for the approved funding period; the fee-based Master in Applied Artificial Intelligence is not covered.', 'Valid proof of English language proficiency must be submitted at the time of application and meet the programme admission criteria; no single IELTS figure is published on the graduate admissions pages.', $j$["Complete online application form via the MBZUAI applicant portal (only one application per cycle)", "CV (academic background, work experience, research publications, programming/coding skills)", "Official bachelor's (and master's for Ph.D. applicants holding one) transcripts and degree certificates or expected-graduation letter", "Statement of purpose (PDF) and, for Ph.D. applicants, research statement (PDF)", "Referee recommendations (minimum two for M.Sc., three for Ph.D.)", "Valid English proficiency proof, passport copy and white-background photo", "Screening exam, then technical interview if invited; AED 200 application fee after the exam (waived at 75%+ score)"]$j$, NULL, NULL, $json$[{"intake": "Fall 2027 - most M.Sc./Ph.D. programmes", "opens": "2026-09-07", "deadline": "2026-12-15", "decisions": "2027-03-31", "offer_response": "2027-04-15", "status": "open"}, {"intake": "Fall 2027 - M.Sc./Ph.D. Computational Biology", "opens": "2026-09-30", "deadline": "2027-01-22", "status": "open"}, {"pattern": "Annual fall-entry cycle: the application portal opens each September, with final deadlines in mid-December (later for Computational Biology and the fee-based MAAI, which carries no funding)"}]$json$);

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (956, 'Tamim Scholarship (Doha Institute for Graduate Studies)', 'Doha Institute for Graduate Studies', 'Qatar', 'Full Tuition + Stipend', 0, 'Scholarship applications follow admission to a master''s programme: admission applications for 2027-2028 opened 1 September 2026 and close 15 January 2027; admitted students are then invited to apply for the Tamim Scholarship.', '2027-01-15', 'fixed', NULL, NULL, $j$["Master's"]$j$, $j$["Social sciences and humanities master's programmes (Politics and International Relations, Sociology and Anthropology, History, Media Studies, Journalism, Philosophy, Comparative Literature, Clinical and Social Psychology, Social Work, Human Rights, Conflict Management and Humanitarian Action, Critical Security Studies, Linguistics and Arabic Lexicography)", "Economics, administration and public policy master's programmes (Public Policy, Development Economics, Public Administration)"]$j$, '[]', NULL, NULL, false, true, $desc$The Tamim Scholarship is the flagship merit scholarship of the Doha Institute for Graduate Studies (DI), the independent graduate institute in Doha founded in 2015 for the social sciences and humanities and public administration/economics. It is offered to outstanding students from within Qatar and abroad who are admitted to the Institute's master's programmes. For international students the package is comprehensive: a 100% tuition waiver, institute student housing, a monthly stipend and health insurance (Qatari students not sponsored by a government entity or employer receive the 100% waiver; resident students receive a need-based waiver of 10-100%). Admission to the master's programmes is itself competitive and runs annually - for the 2027-2028 academic year applications opened on 1 September 2026 and close on 15 January 2027 - after which admitted students are contacted and invited to submit the scholarship application. Teaching at DI is in Arabic: applicants must be able to study and research academically in Arabic, with non-Arabic speakers invited to oral and written Arabic tests before admission, alongside an English-proficiency requirement. The scholarship cannot be combined with any other scholarship, continuation depends on maintaining the required academic standing, and Executive Master's, diploma and specialised certificate programmes are excluded; doctoral students are funded under a separate three-phase scholarship scheme.$desc$, $req$The Tamim Scholarship is for outstanding students admitted to a Doha Institute master's programme, from Qatar and abroad; the detailed benefits depend on the student category (the full package above is the international-student package). Admission requires a full-time bachelor's degree (final-year students may apply if the degree is completed by 1 July of the entry year) meeting the programme's minimum grades in the Institute's grade-requirements table, at least two academic references (an additional employer reference is optional), and - critically for Uzbek applicants - the ability to study and research academically in Arabic (Arabic language of instruction; non-Arabic speakers are tested orally and in writing) plus English proficiency through an accepted examination, whose required scores and exemptions vary by programme. Scholarship conditions: it may not be combined with any other scholarship whatever its source; continuation is contingent on the required academic standing; Executive Master''s, diploma and specialised certificate programmes are not covered; and applicants who previously received an Institute scholarship for a master''s programme - whether or not they completed the degree - are not eligible. Grade minima are published per programme/country table rather than as one GPA figure, and English scores vary, so min_gpa/min_ielts are not recorded.$req$, 'https://www.dohainstitute.edu.qa/en/Admissions-Office/Pages/Scholarships.aspx', 'https://www.dohainstitute.edu.qa/en/Admissions-Office/Pages/Scholarships.aspx', 'https://www.dohainstitute.edu.qa/en/Admissions-Office/Pages/Apply.aspx', 'annual', 'open', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 14) from the Doha Institute's official Scholarships and Admission Conditions and Requirements pages fetched the same day (Tamim Scholarship: merit-based for outstanding master's admittees 'from within the State of Qatar and abroad'; international package = 100% tuition waiver + student housing + monthly stipend + health insurance; Qatari 100% waiver when unsponsored; resident 10-100% need-based waiver; post-admission invitation to apply; no-combination, academic-standing, programme-exclusion and prior-recipient conditions; admission for 2027-2028 opened 1 September 2026 and closes 15 January 2027; Arabic-medium instruction with Arabic tests for non-Arabic speakers and programme-level English requirements; full-time bachelor's with programme/country grade minima; two academic references). award_amount/award_period are NULL with basis 'variable': the institute publishes the components of the international package but no stipend figure, so no amount is stored (award_currency QAR kept as the host currency per the percentage-waiver convention). deadline_date 2027-01-15 is the admission closing that gates the scholarship; status 'open'. eligible_countries empty: the scholarship is open to students from abroad with no nationality list. university_id is NULL and no university_scholarships row is created - the Doha Institute has no record in the universities table (checked 2026-10-27). DI's separate need-conditioned doctoral phase scholarships are deliberately out of scope for this master's record. min_gpa/min_ielts NULL.$note$, NULL, NULL, 'QAR', 'variable', 'variable', NULL, 'For international students: 100% tuition waiver + student housing + monthly stipend + health insurance (stipend amount not published)', 'International Tamim recipients receive a 100% tuition waiver for the master''s programme; continuation depends on maintaining the required academic standing.', 'Arabic is the language of instruction - applicants must be able to study and research academically in Arabic (oral/written Arabic tests for non-Arabic speakers) and must demonstrate English proficiency via an accepted examination; required scores and exemptions vary by programme.', $j$["Online admission application with all required and supporting documents (scholarship application follows admission decisions)", "Copy of passport (international students)", "Bachelor's degree and undergraduate transcripts certified by official authorities (final-year students: latest transcripts; degree by 1 July of the entry year)", "Minimum of two academic references requested via the online application (optional additional employer reference)", "English-proficiency score from an accepted examination (or exemption), and Arabic testing for non-Arabic speakers"]$j$, NULL, NULL, $json$[{"cycle": "2027-2028 admission (scholarship by invitation after admission)", "opens": "2026-09-01", "deadline": "2027-01-15", "status": "open"}, {"pattern": "Annual: admission applications open 1 September and close 15 January; admitted students are then invited to apply for the Tamim Scholarship"}]$json$);

