(3091, 'https://mbzuai.ac.ae/admissions/graduate-phd-admissions', 'Graduate Ph.D. Admissions - Student Funding and Fees - MBZUAI (official)', 'mbzuai.ac.ae', 'scholarship', now(), true, true, now()),
